function halveArray(nums) {
  const heap = [...nums].sort((a, b) => b - a);
  let total = 0;
  for (const value of nums) {
    total += value;
  }
  const goal = total / 2;
  let removed = 0;
  let operations = 0;

  while (removed < goal) {
    const half = heap[0] / 2;
    heap[0] = half;
    removed += half;
    operations++;

    let index = 0;
    while (true) {
      const left = 2 * index + 1;
      const right = left + 1;
      let largest = index;
      if (left < heap.length && heap[left] > heap[largest]) {
        largest = left;
      }
      if (right < heap.length && heap[right] > heap[largest]) {
        largest = right;
      }
      if (largest === index) {
        break;
      }
      [heap[index], heap[largest]] = [heap[largest], heap[index]];
      index = largest;
    }
  }
  return operations;
}

