function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const mode = rand();
  if (size === 'large') {
    const n = pick(1500, 2000);
    if (mode < 0.25) {
      const value = pick(1, 10000000);
      return [Array.from({ length: n }, () => value)];
    }
    if (mode < 0.5) {
      const nums = Array.from({ length: n }, () => pick(1, 100));
      for (let k = pick(1, 5); k > 0; k--) nums[pick(0, n - 1)] = pick(5000000, 10000000);
      return [nums];
    }
    if (mode < 0.75) return [Array.from({ length: n }, () => pick(1, 10000000))];
    return [Array.from({ length: n }, (_, i) => Math.max(1, Math.floor(10000000 / (i + 1))))];
  }
  const n = pick(1, 7);
  if (mode < 0.2) {
    const value = pick(1, 12);
    return [Array.from({ length: n }, () => value)];
  }
  if (mode < 0.35) return [Array.from({ length: n }, () => (rand() < 0.3 ? pick(9000000, 10000000) : pick(1, 10)))];
  return [Array.from({ length: n }, () => pick(1, 20))];
}
